  void SyncHeading(){if(loading||headingChoice==null)return;var p=Editor.CaretPosition.Paragraph;string kind=p==null?"body":p.Tag as string;syncingHeading=true;headingChoice.SelectedIndex=kind=="h1"?1:kind=="h2"?2:0;syncingHeading=false;}
