  public bool Flush(){if(saveTimer!=null)saveTimer.Stop();if(!dirty)return true;if(!app.Save()){status.Text="尚未保存 · 请重试";return false;}dirty=false;status.Text="已保存 · Ctrl+单击打开链接";app.Notes.Changed();return true;}
  int Offset(){return Editor.Document.ContentStart.GetOffsetToPosition(Editor.CaretPosition);}
