  public void UndoEdit(){History(undo,redo);}
  public void RedoEdit(){History(redo,undo);}
  void History(Stack<EditState> from,Stack<EditState> to){if(from.Count==0)return;to.Push(new EditState{Body=lastBody,Offset=Offset()});var state=from.Pop();var doc=NoteCodec.Decode(state.Body);Render(doc);lastBody=state.Body;Note.Body=state.Body;Note.PlainText=doc.PlainText;int max=Editor.Document.ContentStart.GetOffsetToPosition(Editor.Document.ContentEnd);Editor.CaretPosition=Editor.Document.ContentStart.GetPositionAtOffset(Math.Min(max,Math.Max(0,state.Offset)))??Editor.Document.ContentEnd;Editor.Focus();Schedule();}
  static string Plain(Paragraph p){return new TextRange(p.ContentStart,p.ContentEnd).Text.Replace("\uFFFC","");}
  static IEnumerable<Paragraph> Paragraphs(BlockCollection blocks){foreach(var b in blocks){var p=b as Paragraph;if(p!=null)yield return p;var list=b as System.Windows.Documents.List;if(list!=null)foreach(var item in list.ListItems)foreach(var child in Paragraphs(item.Blocks))yield return child;}}
  public NoteDocument Capture(){var doc=new NoteDocument();foreach(var p in Paragraphs(Editor.Document.Blocks)){var box=p.Inlines.OfType<InlineUIContainer>().Select(i=>i.Child).OfType<CheckBox>().FirstOrDefault();var list=p.Parent is ListItem?((ListItem)p.Parent).Parent as System.Windows.Documents.List:null;var block=new NoteBlock{Kind=box!=null?"check":list!=null?(list.MarkerStyle==TextMarkerStyle.Decimal?"number":"bullet"):(p.Tag as string??"body"),Done=box!=null&&box.IsChecked==true,Indent=(int)Math.Round((list==null?p.Margin.Left:list.Margin.Left)/22)};ReadInlines(p.Inlines,block.Runs,null);doc.Blocks.Add(block);}return doc;}
  static bool HasDecoration(Inline inline,TextDecorationLocation location){for(TextElement el=inline;el is Inline;el=el.Parent as TextElement){if((el.Tag as string)=="completion")continue;var decorations=el.ReadLocalValue(Inline.TextDecorationsProperty) as TextDecorationCollection;if(decorations!=null&&decorations.Any(d=>d.Location==location))return true;}return false;}
  static void ReadInlines(InlineCollection inlines,List<NoteRun> output,string link){foreach(var i in inlines){var run=i as Run;var hyperlink=i as Hyperlink;var span=i as Span;if(run!=null)output.Add(new NoteRun{Text=run.Text,Bold=run.FontWeight==FontWeights.Bold||run.FontWeight==FontWeights.SemiBold,Italic=run.FontStyle==FontStyles.Italic,Underline=HasDecoration(run,TextDecorationLocation.Underline),Strike=HasDecoration(run,TextDecorationLocation.Strikethrough),Highlight=run.Background is SolidColorBrush&&((SolidColorBrush)run.Background).Color.A!=0,Link=link});else if(i is LineBreak)output.Add(new NoteRun{Text="\n"});else if(span!=null)ReadInlines(span.Inlines,output,hyperlink!=null&&hyperlink.NavigateUri!=null?hyperlink.NavigateUri.AbsoluteUri:link);}}
  public void Render(NoteDocument doc){loading=true;try{var flow=new FlowDocument{FontFamily=new FontFamily("Segoe UI, Microsoft YaHei UI"),FontSize=15,PagePadding=new Thickness(0),LineHeight=25};flow.SetResourceReference(TextElement.ForegroundProperty,"Ink");int number=0;foreach(var block in doc.Blocks){var p=new Paragraph{Tag=block.Kind,Margin=new Thickness(block.Indent*22,0,0,9),FontSize=block.Kind=="h1"?24:block.Kind=="h2"?19:15};if(block.Kind=="h1"||block.Kind=="h2"){p.FontWeight=FontWeights.SemiBold;p.Margin=new Thickness(block.Indent*22,9,0,10);}InlineCollection target=p.Inlines;
    if(block.Kind=="check"){var box=new CheckBox{IsChecked=block.Done,Margin=new Thickness(0,0,7,0),Focusable=false,VerticalAlignment=VerticalAlignment.Center,ToolTip="标记完成"};AutomationProperties.SetName(box,"便签待办勾选");p.Inlines.Add(new InlineUIContainer(box){BaselineAlignment=BaselineAlignment.Center});var completion=new Span{Tag="completion"};if(block.Done){completion.SetResourceReference(TextElement.ForegroundProperty,"Muted");completion.TextDecorations=TextDecorations.Strikethrough;}p.Inlines.Add(completion);target=completion.Inlines;box.Click+=(s,e)=>{loading=true;if(box.IsChecked==true){completion.SetResourceReference(TextElement.ForegroundProperty,"Muted");completion.TextDecorations=TextDecorations.Strikethrough;}else{completion.ClearValue(TextElement.ForegroundProperty);completion.TextDecorations=null;}loading=false;Record();};}
    foreach(var r in block.Runs){var run=new Run(r.Text){FontWeight=r.Bold?FontWeights.Bold:FontWeights.Normal,FontStyle=r.Italic?FontStyles.Italic:FontStyles.Normal};if(block.Kind=="h1"||block.Kind=="h2")run.FontWeight=FontWeights.SemiBold;var decorations=new TextDecorationCollection();if(r.Underline)decorations.Add(TextDecorations.Underline);if(r.Strike)decorations.Add(TextDecorations.Strikethrough);run.TextDecorations=decorations;if(r.Highlight)run.Background=new SolidColorBrush(Color.FromArgb(95,224,173,45));if(NoteCodec.SafeLink(r.Link)){var h=new Hyperlink(run){NavigateUri=new Uri(r.Link),ToolTip="Ctrl+单击打开链接"};h.SetResourceReference(TextElement.ForegroundProperty,"Accent");h.RequestNavigate+=(s,e)=>{if(Keyboard.Modifiers==ModifierKeys.Control)OpenLink(e.Uri.AbsoluteUri);e.Handled=true;};target.Add(h);}else target.Add(run);}
    if(block.Runs.Count==0)target.Add(new Run(""));
    if(block.Kind=="bullet"||block.Kind=="number"){number=block.Kind=="number"?number+1:0;var list=new System.Windows.Documents.List{MarkerStyle=block.Kind=="number"?TextMarkerStyle.Decimal:TextMarkerStyle.Disc,StartIndex=Math.Max(1,number),Margin=new Thickness(block.Indent*22,0,0,0),Padding=new Thickness(24,0,0,0)};p.Margin=new Thickness(0,0,0,9);list.ListItems.Add(new ListItem(p));flow.Blocks.Add(list);}else{number=0;flow.Blocks.Add(p);}}
    if(flow.Blocks.Count==0)flow.Blocks.Add(new Paragraph());Editor.Document=flow;
   }finally{loading=false;}}
  List<int> SelectedBlocks(){var ps=Paragraphs(Editor.Document.Blocks).ToList();var start=Editor.Selection.Start.Paragraph;var end=Editor.Selection.End.Paragraph;int a=Math.Max(0,ps.IndexOf(start)),b=Math.Max(a,ps.IndexOf(end));return Enumerable.Range(a,b-a+1).ToList();}
  public void SetKind(string kind){var indices=SelectedBlocks();var doc=Capture();bool toggle=kind=="bullet"||kind=="number"||kind=="check";string target=toggle&&indices.All(i=>doc.Blocks[i].Kind==kind)?"body":kind;foreach(int i in indices){doc.Blocks[i].Kind=target;if(target!="check")doc.Blocks[i].Done=false;}Render(doc);Editor.CaretPosition=Paragraphs(Editor.Document.Blocks).ElementAt(indices.Last()).ContentEnd;Editor.Focus();Record();}
  public void Indent(int direction){var indices=SelectedBlocks();var doc=Capture();foreach(int i in indices)doc.Blocks[i].Indent=Math.Max(0,Math.Min(6,doc.Blocks[i].Indent+direction));Render(doc);Editor.CaretPosition=Paragraphs(Editor.Document.Blocks).ElementAt(indices.Last()).ContentEnd;Editor.Focus();Record();}
  public void RefreshTheme(){Editor.Document.Foreground=UI.Brush("Ink");foreach(var p in Paragraphs(Editor.Document.Blocks))RefreshInlines(p.Inlines);}
  void RefreshInlines(InlineCollection collection){foreach(var inline in collection){var h=inline as Hyperlink;if(h!=null)h.Foreground=UI.Brush("Accent");var span=inline as Span;if(span!=null){if((span.Tag as string)=="completion"&&span.TextDecorations!=null&&span.TextDecorations.Any())span.Foreground=UI.Brush("Muted");RefreshInlines(span.Inlines);}}}
  public void Command(RoutedUICommand command){Editor.Focus();command.Execute(null,Editor);Record();}
  public void Decoration(TextDecorationLocation location){Editor.Focus();var current=Editor.Selection.GetPropertyValue(Inline.TextDecorationsProperty) as TextDecorationCollection;var value=current==null?new TextDecorationCollection():current.Clone();bool had=value.Any(d=>d.Location==location);foreach(var d in value.Where(d=>d.Location==location).ToList())value.Remove(d);if(!had)value.Add(location==TextDecorationLocation.Strikethrough?TextDecorations.Strikethrough:TextDecorations.Underline);Editor.Selection.ApplyPropertyValue(Inline.TextDecorationsProperty,value);Record();}
  public void Highlight(){Editor.Focus();var brush=Editor.Selection.GetPropertyValue(TextElement.BackgroundProperty) as SolidColorBrush;Editor.Selection.ApplyPropertyValue(TextElement.BackgroundProperty,brush!=null&&brush.Color.A!=0?Brushes.Transparent:new SolidColorBrush(Color.FromArgb(95,224,173,45)));Record();}
  public void ClearFormat(){Editor.Focus();Editor.Selection.ApplyPropertyValue(TextElement.FontWeightProperty,FontWeights.Normal);Editor.Selection.ApplyPropertyValue(TextElement.FontStyleProperty,FontStyles.Normal);Editor.Selection.ApplyPropertyValue(Inline.TextDecorationsProperty,new TextDecorationCollection());Editor.Selection.ApplyPropertyValue(TextElement.BackgroundProperty,Brushes.Transparent);Record();}
  void Keys(object sender,KeyEventArgs e){if(Keyboard.Modifiers==ModifierKeys.Control&&(e.Key==Key.Z||e.Key==Key.Y)){if(e.Key==Key.Z)UndoEdit();else RedoEdit();e.Handled=true;return;}if(e.Key==Key.Tab){Indent((Keyboard.Modifiers&ModifierKeys.Shift)!=0?-1:1);e.Handled=true;return;}if(e.Key!=Key.Enter||Keyboard.Modifiers!=ModifierKeys.None)return;var p=Editor.CaretPosition.Paragraph;if(p==null)return;var ps=Paragraphs(Editor.Document.Blocks).ToList();var b=Capture().Blocks[ps.IndexOf(p)];if(b.Kind=="body")return;e.Handled=true;
   if(String.IsNullOrWhiteSpace(Plain(p))){SetKind("body");return;}
   if(b.Kind=="bullet"||b.Kind=="number"){loading=true;EditingCommands.EnterParagraphBreak.Execute(null,Editor);loading=false;Record();return;}
   loading=true;Editor.Selection.Text="";Editor.CaretPosition=Editor.CaretPosition.InsertParagraphBreak();loading=false;var next=Editor.CaretPosition.Paragraph;if(next!=null){next.Tag="body";next.FontSize=15;next.FontWeight=FontWeights.Normal;}if(b.Kind=="check")SetKind("check");else if(b.Kind=="h1"||b.Kind=="h2")SetKind("body");else Record();
  }
  static TextPointer AtCharacter(Paragraph p,int count){var pos=p.ContentStart;while(pos!=null&&pos.CompareTo(p.ContentEnd)<0){if(pos.GetPointerContext(LogicalDirection.Forward)==TextPointerContext.Text){string text=pos.GetTextInRun(LogicalDirection.Forward);if(count<=text.Length)return pos.GetPositionAtOffset(count);count-=text.Length;pos=pos.GetPositionAtOffset(text.Length);}else pos=pos.GetNextContextPosition(LogicalDirection.Forward);}return p.ContentEnd;}
  void AutoLink(){var p=Editor.CaretPosition.Paragraph;if(p==null)return;string before=new TextRange(p.ContentStart,Editor.CaretPosition).Text;var match=Regex.Match(before,@"https?://[^\s<>]+(?=\s$)");if(!match.Success||!NoteCodec.SafeLink(match.Value))return;var start=AtCharacter(p,match.Index);var end=AtCharacter(p,match.Index+match.Length);if(start.Parent is Hyperlink||start.Parent is Run&&((Run)start.Parent).Parent is Hyperlink)return;loading=true;var h=new Hyperlink(start,end){NavigateUri=new Uri(match.Value),ToolTip="Ctrl+单击打开链接"};h.SetResourceReference(TextElement.ForegroundProperty,"Accent");h.RequestNavigate+=(s,e)=>{if(Keyboard.Modifiers==ModifierKeys.Control)OpenLink(e.Uri.AbsoluteUri);e.Handled=true;};loading=false;Record();}
  void InsertLink(){var dialog=UI.Dialog(this,"插入链接",380,205);var field=UI.Input("网址","https://");var panel=UI.Stack(UI.Label("网址 · 支持 https:// 或 http://"),field);panel.Margin=new Thickness(20);panel.Children.Add(UI.Button("插入",()=>{if(!NoteCodec.SafeLink(field.Text)){UI.Notice(dialog,"请输入完整的 http 或 https 网址。");return;}dialog.DialogResult=true;},true));dialog.Content=panel;if(dialog.ShowDialog()!=true)return;Editor.Focus();loading=true;if(Editor.Selection.IsEmpty){var start=Editor.CaretPosition;var run=new Run(field.Text,start);var link=new Hyperlink(run.ElementStart,run.ElementEnd){NavigateUri=new Uri(field.Text)};link.SetResourceReference(TextElement.ForegroundProperty,"Accent");Editor.CaretPosition=link.ElementEnd;}else{var link=new Hyperlink(Editor.Selection.Start,Editor.Selection.End){NavigateUri=new Uri(field.Text)};link.SetResourceReference(TextElement.ForegroundProperty,"Accent");}loading=false;Record();}
  void OpenLink(string link){if(!NoteCodec.SafeLink(link))return;try{System.Diagnostics.Process.Start(link);}catch(Exception ex){UI.Notice(this,"无法打开链接："+ex.Message);}}
 }
